def _type_check_with_pyright(
    cls, user_code: str, test_code: str
) -> TypeCheckResult:
    combined_code = user_code + "\n" + test_code
    tokens = list(tokenize.generate_tokens(io.StringIO(combined_code).readline))
    expected_error_lines = set()

    for token in tokens:
        if token.type == tokenize.COMMENT and token.string.strip() == "# expect-type-error":
            expected_error_lines.add(token.start[0])

    reported_error_lines = {}

    with tempfile.NamedTemporaryFile(suffix=".py", mode="w") as tmp:
        tmp.write(combined_code)
        tmp.flush()

        try:
            output = subprocess.check_output(["pyright", tmp.name], stderr=subprocess.STDOUT)
        except subprocess.CalledProcessError as e:
            return TypeCheckResult(
                message=f"Type check failed: {e.output.decode('utf-8')}",
                passed=False,
                debug_info=reported_error_lines,
            )

